-- peanut-release: 3.0.13
-- Append stable identities without renumbering historical records.
-- IDs 1..999999999 reserved for upstream system seeds; new custom IDs start at 1000000000.
SET @menu_identity_ddl=(SELECT IF(COUNT(*)=0,'ALTER TABLE `pa_system_menu` ADD COLUMN `menu_key` VARCHAR(160) NULL','SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_system_menu' AND COLUMN_NAME='menu_key');
PREPARE menu_identity_stmt FROM @menu_identity_ddl;
EXECUTE menu_identity_stmt;
DEALLOCATE PREPARE menu_identity_stmt;
SET @menu_identity_ddl=(SELECT IF(COUNT(*)=0,'ALTER TABLE `pa_system_menu` ADD COLUMN `parent_key` VARCHAR(160) NULL','SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_system_menu' AND COLUMN_NAME='parent_key');
PREPARE menu_identity_stmt FROM @menu_identity_ddl;
EXECUTE menu_identity_stmt;
DEALLOCATE PREPARE menu_identity_stmt;
SET @menu_identity_ddl=(SELECT IF(COUNT(*)=0,'ALTER TABLE `pa_system_menu` ADD COLUMN `module_key` VARCHAR(96) NOT NULL DEFAULT ''application''','SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_system_menu' AND COLUMN_NAME='module_key');
PREPARE menu_identity_stmt FROM @menu_identity_ddl;
EXECUTE menu_identity_stmt;
DEALLOCATE PREPARE menu_identity_stmt;
SET @menu_identity_ddl=(SELECT IF(COUNT(*)=0,'ALTER TABLE `pa_menu_definition` ADD COLUMN `is_show` TINYINT NOT NULL DEFAULT 1','SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_menu_definition' AND COLUMN_NAME='is_show');
PREPARE menu_identity_stmt FROM @menu_identity_ddl;
EXECUTE menu_identity_stmt;
DEALLOCATE PREPARE menu_identity_stmt;
SET @menu_identity_ddl=(SELECT IF(COUNT(*)=0,'ALTER TABLE `pa_menu_definition` ADD COLUMN `is_cache` TINYINT NOT NULL DEFAULT 0','SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_menu_definition' AND COLUMN_NAME='is_cache');
PREPARE menu_identity_stmt FROM @menu_identity_ddl;
EXECUTE menu_identity_stmt;
DEALLOCATE PREPARE menu_identity_stmt;
SET @menu_identity_ddl=(SELECT IF(COUNT(*)=0,'ALTER TABLE `pa_menu_definition` ADD COLUMN `is_disable` TINYINT NOT NULL DEFAULT 0','SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_menu_definition' AND COLUMN_NAME='is_disable');
PREPARE menu_identity_stmt FROM @menu_identity_ddl;
EXECUTE menu_identity_stmt;
DEALLOCATE PREPARE menu_identity_stmt;
CREATE TEMPORARY TABLE menu_identity_seed (type CHAR(1), paths VARCHAR(200), perms VARCHAR(100), menu_key VARCHAR(160), module_key VARCHAR(96));
CREATE TEMPORARY TABLE menu_identity_matches AS SELECT m.id,s.menu_key,s.module_key FROM pa_system_menu m JOIN menu_identity_seed s ON m.type=s.type AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(m.upstream_defaults_json,'$.paths')),m.paths)=s.paths AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(m.upstream_defaults_json,'$.perms')),m.perms)=s.perms;
CREATE TEMPORARY TABLE menu_identity_unique AS SELECT menu_key,MIN(id) AS id FROM menu_identity_matches GROUP BY menu_key HAVING COUNT(*)=1;
UPDATE pa_system_menu m JOIN menu_identity_matches s ON s.id=m.id JOIN menu_identity_unique u ON u.id=s.id AND u.menu_key=s.menu_key SET m.menu_key=s.menu_key,m.module_key=s.module_key WHERE m.menu_key IS NULL;
UPDATE pa_system_menu SET menu_key=CONCAT('custom.',REPLACE(UUID(),'-','')) WHERE menu_key IS NULL;
UPDATE pa_system_menu m LEFT JOIN pa_system_menu p ON p.id=m.pid SET m.parent_key=p.menu_key WHERE m.parent_key IS NULL AND m.pid<>0;
SET @menu_identity_ddl=(SELECT IF(COUNT(*)=0,'ALTER TABLE pa_system_menu ADD UNIQUE KEY uk_system_menu_key (menu_key)','SELECT 1') FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_system_menu' AND INDEX_NAME='uk_system_menu_key');
PREPARE menu_identity_stmt FROM @menu_identity_ddl;
EXECUTE menu_identity_stmt;
DEALLOCATE PREPARE menu_identity_stmt;
ALTER TABLE pa_system_menu MODIFY COLUMN menu_key VARCHAR(160) NOT NULL;
ALTER TABLE pa_system_menu AUTO_INCREMENT=1000000000;
UPDATE pa_menu_definition SET upstream_defaults_json=JSON_SET(upstream_defaults_json,'$.is_show',1,'$.is_cache',0,'$.is_disable',0) WHERE upstream_defaults_json IS NOT NULL AND JSON_EXTRACT(upstream_defaults_json,'$.is_show') IS NULL;
DROP TEMPORARY TABLE menu_identity_unique;
DROP TEMPORARY TABLE menu_identity_matches;
DROP TEMPORARY TABLE menu_identity_seed;
